        />
        <Flashbar
          items={permutations.map(permutation => ({
            type: 'warning',
            content: <ProgressBar {...permutation} variant="flash" />,
            buttonText: permutation.resultButtonText,
            statusIconAriaLabel: 'warning',
          }))}
        />
      </ScreenshotArea>
    </article>
  );
}

